import {
  Controller,
  Post,
  Body,
  UnauthorizedException,
  Get,
  Request,
  UseGuards,
} from '@nestjs/common';
import { AuthService } from './auth.service';
import { JwtAuthGuard } from '../common/guards/jwt-auth.guard';

@Controller('api/auth')
export class AuthController {
  constructor(private authService: AuthService) {}

  @Post('login')
  async login(@Body() body: any) {
    const user = await this.authService.validateUser(
      body.username,
      body.password,
    );
    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }
    return this.authService.login(user);
  }

  @UseGuards(JwtAuthGuard)
  @Get('me')
  getProfile(@Request() req: any) {
    return req.user;
  }
}

import { Module } from '@nestjs/common';
import { AuthService } from './auth.service';
import { AuthController } from './auth.controller';
import { UsersModule } from '../users/users.module';
import { PassportModule } from '@nestjs/passport';
import { JwtModule } from '@nestjs/jwt';
import { JwtStrategy } from './jwt.strategy';

@Module({
  imports: [
    UsersModule,
    PassportModule,
    JwtModule.register({
      secret:
        process.env.JWT_SECRET || 'wakilismart_secret_key_change_me_in_prod',
      signOptions: { expiresIn: (process.env.JWT_EXPIRATION || '1h') as any },
    }),
  ],
  providers: [AuthService, JwtStrategy],
  controllers: [AuthController],
  exports: [AuthService],
})
export class AuthModule {}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { UsersService } from '../users/users.service';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';

@Injectable()
export class AuthService {
  constructor(
    private usersService: UsersService,
    private jwtService: JwtService,
  ) {}

  async validateUser(username: string, pass: string): Promise<any> {
    const user = await this.usersService.findByUsername(username);
    if (user && (await bcrypt.compare(pass, user.passwordHash))) {
      const { passwordHash, ...result } = user;
      return result;
    }
    return null;
  }

  async login(user: any) {
    const payload = { username: user.username, sub: user.id, role: user.role };
    return {
      access_token: this.jwtService.sign(payload),
      user: {
        id: user.id,
        username: user.username,
        role: user.role,
        fullName: user.fullName,
      },
    };
  }
}

import { ExtractJwt, Strategy } from 'passport-jwt';
import { PassportStrategy } from '@nestjs/passport';
import { Injectable } from '@nestjs/common';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor() {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey:
        process.env.JWT_SECRET || 'wakilismart_secret_key_change_me_in_prod',
    });
  }

  async validate(payload: any) {
    return { id: payload.sub, username: payload.username, role: payload.role };
  }
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class BillingService {
  constructor(private prisma: PrismaService) {}

  async generateInvoice(caseId: number) {
    const caseDetails = await this.prisma.case.findUnique({
      where: { id: caseId },
      include: { client: true },
    });

    if (!caseDetails) throw new BadRequestException('Case not found');

    const timeEntries = await this.prisma.timeEntry.findMany({
      where: { caseId, isBilled: false },
    });

    const disbursements = await this.prisma.disbursement.findMany({
      where: { caseId, isBilled: false },
    });

    let subtotal = 0;
    const lineItems = [];

    for (const entry of timeEntries) {
      const hours = entry.durationMinutes / 60;
      const rate = entry.hourlyRate.toNumber();
      const amount = hours * rate;
      subtotal += amount;

      lineItems.push({
        itemType: 'TIME_ENTRY',
        description: `${entry.activityType}: ${entry.description}`,
        quantity: hours,
        unitPrice: rate,
        amount: amount,
        timeEntryId: entry.id,
      });
    }

    for (const disb of disbursements) {
      const disbAmount = disb.amount.toNumber();
      subtotal += disbAmount;
      lineItems.push({
        itemType: 'DISBURSEMENT',
        description: disb.description,
        quantity: 1,
        unitPrice: disbAmount,
        amount: disbAmount,
        disbursementId: disb.id,
      });
    }

    // Check statutory minimum compliance
    const feeSchedule = await this.prisma.feeSchedule.findFirst({
      where: { caseType: caseDetails.caseType },
      orderBy: { effectiveFrom: 'desc' },
    });

    if (
      feeSchedule &&
      subtotal > 0 &&
      subtotal < feeSchedule.statutoryMinimum.toNumber()
    ) {
      throw new BadRequestException(
        `Fee below statutory minimum of KES ${feeSchedule.statutoryMinimum}`,
      );
    }

    const invoiceNumber = `INV-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

    return this.prisma.invoice.create({
      data: {
        invoiceNumber,
        caseId,
        clientId: caseDetails.clientId,
        subtotal,
        taxAmount: 0,
        totalAmount: subtotal,
        balanceDue: subtotal,
        status: 'DRAFT',
        lineItems: {
          create: lineItems,
        },
      },
      include: { lineItems: true },
    });
  }
}

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(
      ROLES_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (!requiredRoles) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();
    return requiredRoles.some((role) => user?.role === role);
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { PrismaService } from '../../prisma/prisma.service';

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  constructor(private prisma: PrismaService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest();
    const user = request.user || { id: null, username: 'System/Public' };
    const method = request.method;

    if (['POST', 'PATCH', 'PUT', 'DELETE'].includes(method)) {
      const action = `${method}_${context.getHandler().name.toUpperCase()}`;
      const entityType = context.getClass().name.replace('Controller', '');

      return next.handle().pipe(
        tap(async (result) => {
          try {
            await this.prisma.auditLog.create({
              data: {
                userId: user.id || null,
                username: user.username,
                action,
                entityType,
                entityId: result?.id || null,
                details: JSON.stringify(request.body),
                ipAddress: request.ip,
              },
            });
          } catch (e) {
            console.error('Audit Log Error', e);
          }
        }),
      );
    }

    return next.handle();
  }
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe } from '@nestjs/common';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  app.enableCors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || [
      'http://localhost:5173',
      'http://192.168.1.100:5173',
    ],
    credentials: true,
  });

  app.setGlobalPrefix('api');

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      transform: true,
      forbidNonWhitelisted: true,
    }),
  );

  await app.listen(process.env.PORT || 3000);
}
bootstrap();

import { Injectable, OnModuleInit } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import * as bcrypt from 'bcrypt';

@Injectable()
export class UsersService implements OnModuleInit {
  constructor(private prisma: PrismaService) {}

  async onModuleInit() {
    await this.seedAdmin();
  }

  async findByUsername(username: string) {
    return this.prisma.user.findUnique({ where: { username } });
  }

  async findById(id: number) {
    return this.prisma.user.findUnique({ where: { id } });
  }

  async create(data: any) {
    const passwordHash = await bcrypt.hash(data.password, 10);
    return this.prisma.user.create({
      data: {
        username: data.username,
        passwordHash,
        fullName: data.fullName,
        role: data.role,
        email: data.email,
        phone: data.phone,
      },
    });
  }

  async seedAdmin() {
    const admin = await this.findByUsername('admin');
    if (!admin) {
      await this.create({
        username: 'admin',
        password: 'password123',
        fullName: 'System Administrator',
        role: 'ADVOCATE',
      });
      console.log('Seeded default admin user');
    }
  }
}
